<div class="edit-layout"><section class="form-card"><h2><?= esc($title) ?></h2><form method="post" enctype="multipart/form-data" action="<?= site_url($route.($editing?'/'.$record['id']:'')) ?>"><?= csrf_field() ?>
<?php foreach($fields as $name=>$meta): $isPassword=$name==='password'; ?><label class="field" for="<?= $name ?>"><?= esc($meta['label']) ?><?php if($isPassword && $editing): ?><small>Leave blank to keep the current password</small><?php endif ?>
<?php if($meta['type']==='select'): ?><select id="<?= $name ?>" name="<?= $name ?>" required><?php foreach($meta['options'] as $option): ?><option value="<?= esc($option,'attr') ?>" <?= ($values[$name]??'')===$option?'selected':'' ?>><?= esc($option) ?></option><?php endforeach ?></select>
<?php else: ?><input id="<?= $name ?>" name="<?= $name ?>" type="<?= $meta['type'] ?>" value="<?= $isPassword?'':esc($values[$name]??'','attr') ?>" <?= ($meta['required'] && !($isPassword && $editing))?'required':'' ?> <?= isset($meta['step'])?'step="'.$meta['step'].'" min="0"':'' ?> <?= $isPassword?'autocomplete="new-password" minlength="4" maxlength="200"':'' ?> <?= $name==='stock_quantity'?'max="1000000"':'' ?> <?= $name==='price'?'max="999999.99"':'' ?> <?= in_array($name,['name','full_name','email'])?'maxlength="100"':'' ?> <?= $name==='username'?'maxlength="50" pattern="[A-Za-z0-9_-]+"':'' ?> <?= $name==='phone'?'maxlength="20"':'' ?>><?php endif ?></label><?php endforeach ?>
<?php if($uploadField): ?><label class="field" for="<?= $uploadField ?>"><?= $uploadField==='avatar'?'Staff avatar':'Product image' ?><input type="file" id="<?= $uploadField ?>" name="<?= $uploadField ?>" accept="image/jpeg,image/png,image/webp" data-image-input><small>JPG, PNG, or WebP · up to 2 MB · maximum 4096 × 4096 pixels. <?= $uploadField==='avatar'?'Cropped to 320 × 320.':'Resized to fit 1000 × 800.' ?></small></label><img class="upload-preview" data-image-preview src="<?= esc(image_url($record[$uploadField]??null),'attr') ?>" alt="Image preview"><?php endif ?>
<div class="form-actions"><a class="button light" href="<?= site_url($route) ?>">Cancel</a><button class="button dark" type="submit"><?= $editing?'Save changes':'Add record' ?> ↗</button></div></form></section><aside class="ritual-card"><span class="eyebrow">THE EMBER WAY</span><span aria-hidden="true">✳</span><h2>Thoughtful details.<br><em>Better days.</em></h2><p>A familiar name, a fresh favorite, a well-stocked counter. The little things make a difference.</p></aside></div>
